def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum possible product obtainable by inserting K multiplication signs
    into the numeric string `num_str` of length N. The product is taken over the
    resulting K+1 integer parts. Leading zeros in parts are ignored (int conversion).
    """
    # Validate input
    if not isinstance(num_str, str) or not num_str.isdigit():
        raise ValueError("num_str must be a string of digits")
    if len(num_str) != N:
        raise ValueError("Provided N does not match length of num_str")
    if K < 0:
        raise ValueError("K must be non‑negative")

    # If K >= N-1 we can place at most N-1 cuts: each digit becomes a part
    if K >= N - 1:
        prod = 1
        for ch in num_str:
            prod *= int(ch)
        return prod

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def best(start: int, cuts_left: int) -> int:
        # If no cuts left, the rest of the string forms a single number
        if cuts_left == 0:
            return int(num_str[start:])
        max_prod = 0
        # The next cut must be placed so that enough digits remain for the remaining cuts
        # we need at least cuts_left digits after the current cut
        for next_start in range(start + 1, N - cuts_left + 1):
            left_val = int(num_str[start:next_start])
            right_prod = best(next_start, cuts_left - 1)
            prod = left_val * right_prod
            if prod > max_prod:
                max_prod = prod
        return max_prod

    return best(0, K)

