def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that
    GCD(P, Q) = x0 and LCM(P, Q) = y0.

    Args:
        x0: The required greatest common divisor of the pair.
        y0: The required least common multiple of the pair.

    Returns:
        The count of all possible ordered pairs (P, Q) meeting the criteria.
        If no such pairs exist, returns 0.

    Raises:
        ValueError: If x0 or y0 is not a positive integer.
    """
    if x0 <= 0 or y0 <= 0:
        raise ValueError("x0 and y0 must be positive integers")

    if y0 % x0 != 0:
        return 0
    n = y0 // x0

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    def isqrt(num: int) -> int:
        if num < 0:
            return 0
        lo, hi = 0, num
        while lo <= hi:
            mid = (lo + hi) // 2
            if mid * mid <= num:
                lo = mid + 1
            else:
                hi = mid - 1
        return hi

    count = 0
    limit = isqrt(n)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

