            src, tgt = rule
            if isinstance(src, str) and isinstance(tgt, str) and src:
                valid_rules.append((src, tgt))
    if not valid_rules:
        # No valid rules to apply
        return 0 if A == B else "NO ANSWER!"

    # BFS initialization
    queue = [(A, 0)]
    visited = set([A])
    max_steps = 10

    while queue:
        current, steps = queue.pop(0)
        if current == B:
            return steps
        if steps >= max_steps:
            continue
        for src, tgt in valid_rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # Move past this index to find overlapping matches
    return "NO ANSWER!"

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform a breadth-first search to transform string A into string B using a list of
    replacement rules. The search is limited to a maximum of 10 transformation steps.
    Each rule is a tuple (source, target). The function returns the minimum number of
    steps needed to achieve B from A, or "NO ANSWER!" if impossible within 10 steps
    or if input is invalid.
    """
    # Basic input validation
    try:
        if not isinstance(A, str) or not isinstance(B, str):
            return "NO ANSWER!"
        if not isinstance(rules, list):
            return "NO ANSWER!"
        for r in rules:
            if not isinstance(r, (tuple, list)) or len(r) != 2:
                return "NO ANSWER!"
            if not isinstance(r[0], str) or not isinstance(r[1], str):
                return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

    # Check trivial case
    if A == B:
        return 0

    from collections import deque

    # BFS queue stores tuples of (current_string, steps_taken)
    queue = deque()
    queue.append((A, 0))
    visited = {A}

    MAX_STEPS = 10

    while queue:
        current, steps = queue.popleft()
        if steps >= MAX_STEPS:
            continue  # cannot go beyond 10 steps

        # Generate all possible next strings
        for src, tgt in rules:
            src_len = len(src)
            start = 0
            while True:
                pos = current.find(src, start)
                if pos == -1:
                    break
                # Replace the found occurrence
                new_str = current[:pos] + tgt + current[pos + src_len :]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                # Move start position to avoid infinite loops on empty src
                start = pos + 1
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
        num (int): The integer to check for primality.

    Returns:
        bool: True if `num` is a prime number, False otherwise.
    """
    try:
        n = int(num)
    except Exception:
        return False

    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    limit = int(n**0.5) + 1
    while i <= limit:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

